export function snapshotBaselineKey(pageId) {
    return `page:${pageId}`;
}
export class MemorySnapshotBaselineStore {
    #snapshots = new Map();
    get(pageId) {
        return this.#snapshots.get(snapshotBaselineKey(pageId));
    }
    set(pageId, snapshot) {
        this.#snapshots.set(snapshotBaselineKey(pageId), snapshot);
    }
    clear(pageId) {
        this.#snapshots.delete(snapshotBaselineKey(pageId));
    }
    clearAll() {
        this.#snapshots.clear();
    }
}
